sys_script.script:
(function executeRule(current, previous) {
    // glide_time values are stored as '1970-01-01 HH:MM:SS' (UTC), so read only the time of day.
    function secondsOfDay(value) {
        var m = /(\d{1,2}):(\d{2})(?::(\d{2}))?\s*$/.exec(String(value || ''));
        return m ? parseInt(m[1], 10) * 3600 + parseInt(m[2], 10) * 60 + parseInt(m[3] || '0', 10) : null;
    }

    var inSeconds = secondsOfDay(current.getValue('check_in'));
    if (inSeconds === null) return;

    var configGr = new GlideRecord('x_2316161_bjit_e_0_att_cfg');
    configGr.addQuery('active', true);
    configGr.setLimit(1);
    configGr.query();
    if (!configGr.next()) return;

    var startSeconds = secondsOfDay(configGr.getValue('work_start'));
    var gracePeriod = parseInt(configGr.getValue('grace_period') || '0', 10);

    if (startSeconds !== null)
        current.setValue('is_late', inSeconds > (startSeconds + gracePeriod * 60));
})(current, previous);
